/* @autogenerated */
import { signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { firstValueFrom } from 'rxjs';
import { APP_CONFIG } from '../config/app-config.service';
import { AppConfig, emptyConfig } from '../config/app-config.model';
import { ANONYMOUS_USER } from '../identity/user-info.model';
import { APP_STATE_CHANNEL, AppStateMessage, AppStateService, ContextValue } from './app-state.service';

const STORED_KEYS = ['state-item-selected-language', 'state-item-selected-tenant', 'state-item-context'];

// BroadcastChannel entrega los mensajes en una tarea posterior
const delivered = () => new Promise((resolve) => setTimeout(resolve, 50));

describe('AppStateService', () => {
  let config: ReturnType<typeof signal<AppConfig>>;

  function create(): AppStateService {
    TestBed.configureTestingModule({ providers: [{ provide: APP_CONFIG, useValue: config }] });
    return TestBed.inject(AppStateService);
  }

  beforeEach(() => {
    STORED_KEYS.forEach((key) => localStorage.removeItem(key));
    config = signal<AppConfig>({ ...emptyConfig('test'), i18n: { 'default-lang': 'es' }, tenant: { default: 'acme' } });
  });

  afterEach(() => STORED_KEYS.forEach((key) => localStorage.removeItem(key)));

  describe('language and tenant', () => {
    it('follow the configured defaults until the user chooses', () => {
      const state = create();
      expect(state.language()).toBe('es');
      expect(state.tenant()).toBe('acme');

      config.set({ ...config(), i18n: { 'default-lang': 'fr' } });
      expect(state.language()).toBe('fr');
      expect(localStorage.getItem('state-item-selected-language')).toBeNull();
    });

    it('persist the choice, which wins over a later default', () => {
      const state = create();
      state.language.set('en');

      expect(JSON.parse(localStorage.getItem('state-item-selected-language')!)).toEqual({ data: 'en' });
      config.set({ ...config(), i18n: { 'default-lang': 'fr' } });
      expect(state.language()).toBe('en');
    });

    it('restore the stored choice', () => {
      localStorage.setItem('state-item-selected-tenant', JSON.stringify({ data: 'globex' }));
      expect(create().tenant()).toBe('globex');
    });

    it('ignore an unreadable stored value', () => {
      localStorage.setItem('state-item-selected-tenant', '{not json');
      expect(create().tenant()).toBe('acme');
    });

    it('expose observables for RxJS consumers', async () => {
      const state = create();
      state.tenant.set('globex');
      TestBed.tick();
      expect(await firstValueFrom(state.tenant$)).toBe('globex');
    });
  });

  describe('users', () => {
    it('reads an unknown identity as anonymous without creating state', () => {
      const state = create();
      expect(state.user('other')()).toEqual(ANONYMOUS_USER);
      expect(state.users()).toEqual({});
    });

    it('keeps the user of each identity', () => {
      const state = create();
      state.setUser('main', { authenticated: true, uid: 'u1' });
      expect(state.user('main')().uid).toBe('u1');
      expect(state.user('other')().authenticated).toBeFalse();
    });
  });

  describe('context', () => {
    it('reads an unknown key as null without creating state', () => {
      const state = create();
      expect(state.contextValue('org')()).toBeNull();
      expect(state.contexts()).toEqual({});
    });

    it('splits fixed and filter values', () => {
      const state = create();
      state.setContext('tenant', ContextValue.fixed('tenant', 't1'));
      state.setContext('org', ContextValue.default('org', 'o1'));
      state.setContext('q', ContextValue.filter('q', 'x'));
      state.setContext('empty', ContextValue.null('empty'));

      expect(state.fixedValues()).toEqual({ tenant: 't1', org: 'o1' });
      expect(state.filterValues()).toEqual({ tenant: 't1', q: 'x' });
    });

    it('is persisted and restored as ContextValue', () => {
      create().setContext('tenant', ContextValue.fixed('tenant', 't1'));
      TestBed.resetTestingModule();

      const restored = create().contextValue('tenant')();
      expect(restored).toBeInstanceOf(ContextValue);
      expect(restored?.value).toBe('t1');
      expect(restored?.fixed).toBeTrue();
    });
  });

  describe('deprecated API', () => {
    it('reading userInfo or context does not create state', () => {
      const state = create();
      expect(state.userInfo['main']).toBeDefined();
      expect(state.context['org']).toBeDefined();
      expect(state.users()).toEqual({});
      expect(state.contexts()).toEqual({});
    });

    it('writes through to the signals', () => {
      const state = create();
      state.userInfo['main'].set({ authenticated: true });
      state.context['org'].set(ContextValue.fixed('org', 'o1'));
      expect(state.user('main')().authenticated).toBeTrue();
      expect(state.contextValue('org')()?.value).toBe('o1');
    });
  });

  describe('sync between tabs', () => {
    let otherTab: BroadcastChannel;
    let received: AppStateMessage[];

    beforeEach(() => {
      received = [];
      otherTab = new BroadcastChannel(APP_STATE_CHANNEL);
      otherTab.onmessage = (event) => received.push(event.data);
    });

    afterEach(() => otherTab.close());

    it('publishes language, tenant and logout', async () => {
      const state = create();
      state.language.set('en');
      state.tenant.set('globex');
      state.setUser('main', { authenticated: true });
      state.setUser('main', ANONYMOUS_USER);
      await delivered();

      expect(received).toEqual([
        { type: 'language', value: 'en' },
        { type: 'tenant', value: 'globex' },
        { type: 'logout', identity: 'main' },
      ]);
    });

    it('does not publish the login nor unchanged values', async () => {
      const state = create();
      state.setUser('main', { authenticated: true });
      state.tenant.set('acme');
      await delivered();

      expect(received).toEqual([]);
    });

    it('applies the changes of another tab without echoing them', async () => {
      const state = create();
      state.setUser('main', { authenticated: true });
      otherTab.postMessage({ type: 'language', value: 'pt' });
      otherTab.postMessage({ type: 'tenant', value: 'globex' });
      otherTab.postMessage({ type: 'logout', identity: 'main' });
      await delivered();

      expect(state.language()).toBe('pt');
      expect(state.tenant()).toBe('globex');
      expect(state.user('main')().authenticated).toBeFalse();
      expect(received).toEqual([]);
    });

    it('ignores unknown messages', async () => {
      const state = create();
      otherTab.postMessage({ type: 'language', value: 42 });
      otherTab.postMessage('logout');
      await delivered();

      expect(state.language()).toBe('es');
    });

    it('closes the channel when destroyed', async () => {
      const state = create();
      TestBed.resetTestingModule();
      otherTab.postMessage({ type: 'tenant', value: 'globex' });
      await delivered();

      expect(state.tenant()).toBe('acme');
    });
  });
});
